/** Reasons the contract is not draftable. */
export enum V1Reason {
  /** The subscription contract was not found. */
  SUBSCRIPTION_CONTRACT_NOT_FOUND = 'SUBSCRIPTION_CONTRACT_NOT_FOUND',
  /** Subscription contract contains items from catalogs which do not support edit. */
  UNSUPPORTED_CATALOG = 'UNSUPPORTED_CATALOG',
  /** Subscription contract was created via an unsupported channel type. */
  UNSUPPORTED_CHANNEL_TYPE = 'UNSUPPORTED_CHANNEL_TYPE',
  /** Site and subscription contract currencies are different. */
  CURRENCY_MISMATCH = 'CURRENCY_MISMATCH',
  /** Site and subscription contract weight units are different. */
  WEIGHT_UNIT_MISMATCH = 'WEIGHT_UNIT_MISMATCH',
  /** An active draft for this subscription is owned by another identity. */
  DRAFT_ALREADY_EXISTS_FOR_ANOTHER_OWNER = 'DRAFT_ALREADY_EXISTS_FOR_ANOTHER_OWNER',
  /** Subscription is on its last billing cycle. */
  LAST_CYCLE = 'LAST_CYCLE',
  /** Subscription is in a grace period after a failed charge. */
  GRACE_PERIOD = 'GRACE_PERIOD',
  /** The subscription's current status does not permit editing. */
  UNSUPPORTED_STATUS = 'UNSUPPORTED_STATUS',
  /** Editing of the subscription is not allowed, without a more specific reason. */
  SUBSCRIPTION_NOT_EDITABLE = 'SUBSCRIPTION_NOT_EDITABLE',
  /** Subscription contains items from more than 1 catalog. */
  MULTIPLE_CATALOGS = 'MULTIPLE_CATALOGS',
}

/** @enumType */
export type V1ReasonWithLiterals =
  | V1Reason
  | 'SUBSCRIPTION_CONTRACT_NOT_FOUND'
